import { isNil } from "lodash-es";
import { watch } from "vue";
const useAutoRunPlugin = (fetchInstance, { manual, refreshDeps = [], refreshDepsAction }) => {
  if (isNil(refreshDeps)) {
    return {};
  }
  watch(refreshDeps, () => {
    if (!manual) {
      refreshDepsAction ? refreshDepsAction() : fetchInstance.refresh();
    }
  });
  return {};
};
export {
  useAutoRunPlugin
};
